def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def normalize_email(value):
        angle_match = re.search(r"<([^<>]*)>", value)
        if angle_match:
            value = angle_match.group(1)

        value = value.strip().lower()

        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")
        if not local or "." not in domain:
            return ""
        if domain.startswith(".") or domain.endswith("."):
            return ""

        if domain in {"gmail.com", "googlemail.com"}:
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"
            if not local:
                return ""

        return f"{local}@{domain}"

    def normalize_phone(value):
        marker = re.search(r"(?:ext|x|#)", value, flags=re.IGNORECASE)
        if marker:
            value = value[:marker.start()]

        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        if len(digits) != 10 or digits[0] in {"0", "1"}:
            return ""
        return digits

    def normalize_zip(value):
        value = value.strip()

        if re.fullmatch(r"\d{5}-\d{4}", value):
            value = value.split("-", 1)[0]

        if re.fullmatch(r"\d{4}", value):
            value = "0" + value

        if not re.fullmatch(r"\d{5}", value):
            return ""
        return value

    def parse_updated(value):
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated value: {value!r}")

    def normalize_tags(value):
        return {
            tag.strip().lower()
            for tag in re.split(r"[;,]", value)
            if tag.strip()
        }

    def is_opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    normalized_rows = []

    for index, row in enumerate(rows):
        normalized = {
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": normalize_email(row["email"]),
            "phone": normalize_phone(row["phone"]),
            "zip": normalize_zip(row["zip"]),
            "tags": normalize_tags(row["tags"]),
            "opted_out": is_opted_out(row["opted_out"]),
            "updated": parse_updated(row["updated"]),
            "source": row["source"].strip().lower(),
            "_index": index,
        }

        if normalized["email"] or normalized["phone"]:
            normalized_rows.append(normalized)

    # Union-find groups rows connected by email or by (phone, last name).
    parent = list(range(len(normalized_rows)))
    rank = [0] * len(normalized_rows)

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        root_a = find(a)
        root_b = find(b)

        if root_a == root_b:
            return

        if rank[root_a] < rank[root_b]:
            root_a, root_b = root_b, root_a

        parent[root_b] = root_a
        if rank[root_a] == rank[root_b]:
            rank[root_a] += 1

    email_owner = {}
    phone_name_owner = {}

    for i, row in enumerate(normalized_rows):
        email = row["email"]
        if email:
            if email in email_owner:
                union(i, email_owner[email])
            else:
                email_owner[email] = i

        phone = row["phone"]
        last_name = row["last_name"]
        if phone and last_name:
            key = (phone, last_name.casefold())
            if key in phone_name_owner:
                union(i, phone_name_owner[key])
            else:
                phone_name_owner[key] = i

    groups = {}
    for i, row in enumerate(normalized_rows):
        groups.setdefault(find(i), []).append(row)

    def choose_field(group, field):
        candidates = [row for row in group if row[field]]
        if not candidates:
            return ""

        chosen = max(
            candidates,
            key=lambda row: (
                row["source"] == "manual",
                row["updated"],
                -row["_index"],
            ),
        )
        return chosen[field]

    output = []

    for group in sorted(
        groups.values(),
        key=lambda group: min(row["_index"] for row in group),
    ):
        tags = set()
        for row in group:
            tags.update(row["tags"])

        latest = max(row["updated"] for row in group)

        output.append({
            "first_name": choose_field(group, "first_name"),
            "last_name": choose_field(group, "last_name"),
            "zip": choose_field(group, "zip"),
            "email": choose_field(group, "email"),
            "phone": choose_field(group, "phone"),
            "source": choose_field(group, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(row["opted_out"] for row in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return output
